317	    /**
318	     * 确认 OPEN 升级记录：仅操作当时的当前指挥人可确认（待接受期间目标人无确认权，
319	     * 交接接受后旧指挥人失去确认权），提交非空处置说明后进入 ACKNOWLEDGED，
320	     * 记录确认人与 UTC 时刻。已 CANCELLED/ACKNOWLEDGED 或不存在记录均为 409。
321	     */
322	    @Transactional
323	    public EscalationView acknowledgeEscalation(String incidentKey, String actor,
324	                                                EscalationAckRequest req) {
325	        String commandKey = requireText(req.commandKey(), "commandKey");
326	        String note = requireText(req.note(), "note");
327	        Incident incident = lockIncident(incidentKey);
328	        return runIdempotent(commandKey, "escalation_ack", hash(incidentKey, actor, note),
329	                EscalationView.class, () -> {
330	                    requireCommander(incident, actor);
331	                    Escalation escalation = escalations.findByIncident(incident.id())
332	                            .orElseThrow(() -> ApiException.conflict("当前没有可确认的升级记录"));
333	                    if (escalation.status() != EscalationStatus.OPEN) {
334	                        throw ApiException.conflict(
335	                                "升级记录状态为 " + escalation.status() + "，不能确认");
336	                    }
337	                    Instant ackedAt = now();
338	                    int updated = escalations.acknowledge(escalation.id(), note, actor, ackedAt);
339	                    if (updated == 0) {
340	                        throw ApiException.conflict("升级记录已被并发处理，不能确认");
341	                    }
342	                    return toEscalationView(
343	                            escalations.findByIncident(incident.id()).orElseThrow());
344	                });
345	    }
