29	/**
30	 * 并发边界测试：验证行锁串行化与幂等键唯一约束下，
31	 * 并发接管、交接接受与状态推进按事务提交顺序生效，且同键重放安全。
32	 */
33	@SpringBootTest
34	class IncidentConcurrencyTest {
35	
36	    @Autowired
37	    private IncidentService service;
38	
39	    @Autowired
40	    private JdbcTemplate jdbc;
41	
42	    @BeforeEach
43	    void clean() {
44	        jdbc.update("DELETE FROM command_keys");
45	        jdbc.update("DELETE FROM incident_status_history");
46	        jdbc.update("DELETE FROM incident_transfers");
47	        jdbc.update("DELETE FROM incident_actions");
48	        jdbc.update("DELETE FROM incident_task_blockers");
49	        jdbc.update("DELETE FROM incident_tasks");
50	        jdbc.update("DELETE FROM incidents");
51	    }
52	
53	    private static String key() {
54	        return "INC-" + UUID.randomUUID();
55	    }
56	
57	    /**
58	     * 并发提交一批任务并收集结果（成功值或异常）。
59	     */
60	    private static <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
61	        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
62	        try {
63	            CountDownLatch ready = new CountDownLatch(tasks.size());
64	            CountDownLatch start = new CountDownLatch(1);
65	            List<Future<Object>> futures = new ArrayList<>();
66	            for (Callable<T> task : tasks) {
67	                futures.add(pool.submit(() -> {
68	                    ready.countDown();
69	                    start.await(5, TimeUnit.SECONDS);
70	                    try {
71	                        return task.call();
72	                    } catch (Exception e) {
73	                        return e;
74	                    }
75	                }));
76	            }
77	            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
78	            start.countDown();
79	            List<Object> results = new ArrayList<>();
80	            for (Future<Object> future : futures) {
81	                results.add(future.get(30, TimeUnit.SECONDS));
82	            }
83	            return results;
84	        } finally {
85	            pool.shutdownNow();
86	        }
87	    }
88	
89	    @Test
90	    void concurrentTakeover_exactlyOneWins() throws Exception {
91	        String ik = "INC-200";
92	        service.report(new ReportRequest(ik, "S1", "并发接管", "r"));
93	        List<Callable<IncidentView>> tasks = new ArrayList<>();
94	        for (int i = 0; i < 4; i++) {
95	            String actor = "actor-" + i;
96	            tasks.add(() -> service.takeover(ik, actor, new TakeoverRequest(key())));
97	        }
98	        List<Object> results = runConcurrently(tasks);
99	        long successes = results.stream().filter(IncidentView.class::isInstance).count();
100	        long illegal = results.stream().filter(ApiException.class::isInstance)
101	                .map(ApiException.class::cast)
102	                .filter(e -> e.status().value() == 422).count();
103	        assertThat(successes).isEqualTo(1);
104	        assertThat(illegal).isEqualTo(3);
105	        // 状态只流转一次
106	        assertThat(service.history(ik).statusHistory())
107	                .filteredOn(s -> "COMMANDING".equals(s.toStatus())).hasSize(1);
108	    }
109	
110	    @Test
111	    void concurrentAcceptAndResolve_commitOrderWins() throws Exception {
112	        String ik = "INC-201";
113	        service.report(new ReportRequest(ik, "S1", "交接与解决并发", "r"));
114	        service.takeover(ik, "alice", new TakeoverRequest(key()));
115	        service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"));
116	        service.initiateTransfer(ik, "alice", new TransferRequest(key(), "bob"));
117	
118	        List<Object> results = runConcurrently(List.of(
119	                () -> service.acceptTransfer(ik, "bob", new TransferAcceptRequest(key())),
120	                () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "RESOLVED"))));
121	
122	        long successes = results.stream().filter(IncidentView.class::isInstance).count();
123	        long failures = results.stream().filter(ApiException.class::isInstance).count();
124	        assertThat(successes).isEqualTo(1);
125	        assertThat(failures).isEqualTo(1);
126	
127	        IncidentView end = service.get(ik);
128	        var transfers = service.history(ik).transfers();
129	        if ("RESOLVED".equals(end.status())) {
130	            // 解决先提交：交接接受必须失败，指挥人不变
131	            assertThat(end.commander()).isEqualTo("alice");
132	            assertThat(transfers.get(0).status()).isEqualTo("PENDING");
133	        } else {
134	            // 接受先提交：旧指挥人的解决必须失败，状态仍 CONTAINED，指挥人已切换
135	            assertThat(end.status()).isEqualTo("CONTAINED");
136	            assertThat(end.commander()).isEqualTo("bob");
137	            assertThat(transfers.get(0).status()).isEqualTo("ACCEPTED");
138	        }
139	    }
140	
141	    @Test
142	    void concurrentSameCommandKey_singleEffect() throws Exception {
143	        String ik = "INC-202";
144	        service.report(new ReportRequest(ik, "S1", "同键并发", "r"));
145	        String commandKey = key();
146	        List<Callable<IncidentView>> tasks = new ArrayList<>();
147	        for (int i = 0; i < 3; i++) {
148	            tasks.add(() -> service.takeover(ik, "alice", new TakeoverRequest(commandKey)));
149	        }
150	        List<Object> results = runConcurrently(tasks);
151	
152	        List<IncidentView> successes = results.stream().filter(IncidentView.class::isInstance)
153	                .map(IncidentView.class::cast).toList();
154	        assertThat(successes).isNotEmpty();
155	        // 所有成功响应一致，且接管只生效一次
156	        assertThat(successes).allSatisfy(v -> assertThat(v).isEqualTo(successes.get(0)));
157	        assertThat(service.get(ik).commander()).isEqualTo("alice");
158	        assertThat(service.history(ik).statusHistory())
159	                .filteredOn(s -> "COMMANDING".equals(s.toStatus())).hasSize(1);
160	        Integer keyCount = jdbc.queryForObject(
161	                "SELECT COUNT(*) FROM command_keys WHERE command_key = ?", Integer.class, commandKey);
162	        assertThat(keyCount).isEqualTo(1);
163	    }
