28	 * 使环检测与边写入相对其他创建串行化，保证并发反向依赖下最终图无环。
29	 */
30	@Repository
31	public class IncidentTaskRepository {
32	
33	    /** 依赖图全局锁行的固定主键。 */
34	    private static final long GRAPH_LOCK_ID = 1L;
35	
36	    private final JdbcTemplate jdbc;
