package com.example.starter.incident;

/**
 * 互助租约状态：ACTIVE 仍有未归还量；CLOSED 恰好还完已关闭，为终态。
 */
public enum AidLeaseStatus {
    ACTIVE,
    CLOSED
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件资源可用量实体，对应 incident_resource_inventories 表。
 * availableQuantity 为当前可征调数量（单位件），恒满足 &gt;= 0：
 * 征调提交时原子扣减，租约恰好还完关闭时一次性累计加回。
 * 时间均为 UTC。
 */
public record ResourceInventory(
        long id,
        long incidentId,
        String resourceCode,
        int availableQuantity,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 跨事件互助资源征调租约实体，对应 resource_aid_leases 表。
 * 来源事件与目标事件在首次征调时固定，历史租约始终保留这两个事件；
 * quantity 为征调总量（件），returnedQuantity 为分次归还累计量，
 * 恒满足 0 &lt;= returnedQuantity &lt;= quantity；
 * exclusive 为 true 表示资源被本租约排他占用；
 * status 仅 ACTIVE→CLOSED，恰好还完时关闭并一次性释放来源额度；
 * expiresAt 为 UTC 到期时刻，到期不自动虚构归还。
 * closedAt 仅 CLOSED 有值，否则为空。
 */
public record AidLease(
        long id,
        String requestId,
        long sourceIncidentId,
        long targetIncidentId,
        String resourceCode,
        int quantity,
        int returnedQuantity,
        boolean exclusive,
        AidLeaseStatus status,
        Instant expiresAt,
        String createdBy,
        Instant createdAt,
        Instant closedAt) {

    /** 当前未归还数量（件）。 */
    public int outstandingQuantity() {
        return quantity - returnedQuantity;
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 互助租约分次归还流水实体，对应 resource_aid_returns 表。
 * quantity 为本次实际归还数量（件，正数）；returnedAt 为归还 UTC 时刻。
 */
public record AidReturn(
        long id,
        long leaseId,
        int quantity,
        String returnedBy,
        Instant returnedAt,
        Instant createdAt) {
}

