        return aid.listLeasesByIncident(incident.id()).stream()
                .map(lease -> toLeaseView(lease,
                        incidents.findByKey(lease.sourceIncidentId()).map(Incident::incidentKey).orElse(null),
                        incidents.findByKey(lease.targetIncidentId()).map(Incident::incidentKey).orElse(null)))
