        assertThat(service.listInventories("A")).singleElement()
                .satisfies(i -> assertThat(i.availableQuantity()).isEqualTo(2));

        // 归还 2：待还 1，A 可用量回到 4，一条归还流水
        AidLeaseDetailView afterReturn2 = service.returnLease("REQ-1", "bob",
